#!/usr/bin/env python3
"""Apply script: recover Optical/Physiotherapy/DHA-screening benefit rows
from image-only pages in a Cigna Smart Care table-of-benefits PDF.

Run from the HealthCross repo root: python3 apply_smart_care_image_page_ocr.py
"""
import base64, hashlib, os, sys

MARKER = "SMART_CARE_IMAGE_PAGE_OCR_2026_08_04"

FILES = [
    {
        'path': 'app/ingestion/international_tob.py',
        'sha256': '64e3927bb421291a11420aa7ab6fe754ae8b6cccf2aa3c98a403bc8908fd2ded',
        'size': 29300,
        'b64': '',
    },
    {
        'path': 'app/reference/benefit_category_mapping.py',
        'sha256': 'ec1a7a7d52efdbd72046625c425d6d8db38be1ed9590e7f9fd4050c8c4bea95e',
        'size': 37050,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("Next: python3 -m pytest -q   (should show 441 passed)")
        print("Then: git add -A && git commit -m '...' && git push")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
